  "honest: truth, admit +1.5",
  "deceptive (a liar): lie, conceal +0.7",
  "guarded (someone who shuts doors): lock, exclude, hide +0.7",
  "open (someone who opens doors): welcome, share, trust +0.7",
  "fair: evidence, restraint",
  "suspicious (quick to suspect): accuse, surveil, rumor +0.7",
  "",
